/// IRRS Kernel V8 — Canonical Implementation
///
/// Implements the operator mathematics from `kernel_reference.md` (Metatron Dynamics,
/// Kernel V8, 2026-09-27; operational discipline added 2026-09-29).
///
/// File responsibilities (separation rule, section 13 of kernel_reference.md):
///   `operators.rs`          — what acts: operators, data structures, ρ computation
///   `derived_invariants.rs` — what is produced: confirmed Part I invariant functions
///   `region.rs`             — M Regional Instantiation Prerequisite enforcement
///
/// ─── Domain-specificity principle ────────────────────────────────────────────
///
/// Complexity makes domain-specific parameters structurally unavoidable.
///
/// The relational structure of a hydrogen atom, a magnetospheric current sheet,
/// a biochemical oscillator, and a social network are incommensurable. The
/// characteristic scale at which antisymmetric circulation saturates (χ₀), the
/// ceiling of the coupling coefficient (ρ_base), and the cross-topology coupling
/// magnitudes (cc) are properties of the declared domain — not universal constants
/// with unknown numerical values.
///
/// This is not an incomplete specification. It is the correct structure of the
/// framework. Complexity of the declared domain is what determines the applicable
/// values. A domain that has not established these parameters through M has not
/// completed its declaration; the kernel correctly holds no value and supplies no
/// default.
///
/// Every application of Kernel V8 operators to a new domain requires M to
/// establish domain-specific values for all operator parameters before any
/// operator is applied. An application that assigns universal or cross-domain
/// parameter values violates the admissibility condition.
///
/// ─────────────────────────────────────────────────────────────────────────────
///
/// This kernel is frozen. No modification is authorized.
/// Where this crate and `kernel_reference.md` differ, the source file governs;
/// a difference is a finding to be returned to Origin.

pub mod operators;
pub mod derived_invariants;
pub mod region;

/// Kernel V8 — Canonical Relational Operators
///
/// Implements the operator forms from `kernel_reference.md`, sections 11–12.
/// This file is `operators.rs`. What acts is here.
/// Derived invariants are in `derived_invariants.rs`. What is produced is there.
/// Do not add derived invariants to this file.
///
/// Frozen at Kernel V8. No modification is authorized.
/// Where this file and `kernel_reference.md` differ, this file governs.
/// A difference is a finding to be returned to Origin.
///
/// Source authority: Metatron Dynamics Kernel V8 (2026-09-27; discipline 2026-09-29).

// ─── EdgeProvenance ──────────────────────────────────────────────────────────

/// Every declared edge carries one of three provenances.
/// A relation with no declared provenance is fabricated within D.
/// Section 12.7 of kernel_reference.md.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EdgeProvenance {
    /// Within-family spatial continuation — declared from observable or device geometry.
    /// Open boundary: no wraparound.
    Continuation,
    /// Cross-family spatial coupling — declared from physical coupling mechanism.
    Coupling,
    /// Relational-evolutionary — connects E_prior[e] to E_current[e] across one
    /// declared process step. Not declared in the spatial edge list. Use PersistenceState.
    Persistence,
}

// ─── DeclaredRelations ───────────────────────────────────────────────────────

/// Declared relational structure.
///
/// Production constructor — requires explicit provenance for every edge.
/// `Persistence` edges are not declared here; use `PersistenceState`.
/// Section 12.1 of kernel_reference.md.
pub struct DeclaredRelations {
    pub n_nodes: usize,
    n_edges: usize,
    edges: Vec<(usize, usize)>,       // edges[e] = (src, tgt)
    provenance: Vec<EdgeProvenance>,
    /// out[i] — edge indices leaving node i (ABR B and R)
    pub out: Vec<Vec<usize>>,
    /// inc[i] — edge indices entering node i (ABR B and R)
    pub inc: Vec<Vec<usize>>,
    /// adj_plus[e] = succ(e) — edges starting where e ends (Primary Σ, ABR B/R)
    pub adj_plus: Vec<Vec<usize>>,
    /// adj_minus[e] = pred(e) — edges ending where e starts (Primary Σ, ABR B/R)
    pub adj_minus: Vec<Vec<usize>>,
}

impl DeclaredRelations {
    pub fn from_edges_with_provenance(
        n_nodes: usize,
        edges: Vec<(usize, usize)>,
        provenance: Vec<EdgeProvenance>,
    ) -> Self {
        assert_eq!(
            edges.len(), provenance.len(),
            "every declared edge must have a declared provenance"
        );
        let n_edges = edges.len();

        let mut out = vec![vec![]; n_nodes];
        let mut inc = vec![vec![]; n_nodes];
        for (e, &(src, tgt)) in edges.iter().enumerate() {
            assert!(
                src < n_nodes && tgt < n_nodes,
                "edge {} ({}, {}) references node outside declared range [0, {})",
                e, src, tgt, n_nodes
            );
            out[src].push(e);
            inc[tgt].push(e);
        }

        // adj_plus[e] = edges f such that source(f) == target(e)
        // adj_minus[e] = edges f such that target(f) == source(e)
        let mut adj_plus  = vec![vec![]; n_edges];
        let mut adj_minus = vec![vec![]; n_edges];
        for e in 0..n_edges {
            let tgt_e = edges[e].1;
            let src_e = edges[e].0;
            adj_plus[e]  = out[tgt_e].clone();
            adj_minus[e] = inc[src_e].clone();
        }

        DeclaredRelations {
            n_nodes, n_edges, edges, provenance, out, inc, adj_plus, adj_minus,
        }
    }

    pub fn n_edges(&self)            -> usize         { self.n_edges }
    pub fn src(&self, e: usize)      -> usize         { self.edges[e].0 }
    pub fn tgt(&self, e: usize)      -> usize         { self.edges[e].1 }
    pub fn provenance(&self, e: usize) -> EdgeProvenance { self.provenance[e] }
}

// ─── NodeField ───────────────────────────────────────────────────────────────

/// Numerical projection through M over declared nodes.
/// Input to both kernels.
///
/// data[c][i] — component c, node i.
/// All values must be finite (∈ D).
/// Section 12.2 of kernel_reference.md.
pub struct NodeField {
    pub data: Vec<Vec<f64>>,
    /// n_components
    pub k: usize,
    /// n_nodes
    pub n: usize,
}

impl NodeField {
    pub fn new(data: Vec<Vec<f64>>) -> Self {
        assert!(!data.is_empty(), "NodeField must have at least one component");
        let n = data[0].len();
        for (c, col) in data.iter().enumerate() {
            assert_eq!(col.len(), n,
                "component {} has {} values but component 0 has {}", c, col.len(), n);
            for (i, &v) in col.iter().enumerate() {
                assert!(v.is_finite(),
                    "NodeField component {} node {}: value {} is not finite (∈ D)", c, i, v);
            }
        }
        let k = data.len();
        NodeField { data, k, n }
    }
}

// ─── PrimaryEdgeField ────────────────────────────────────────────────────────

/// Output of primary kernel operators.
/// field[c][e] — component c, edge e.
/// Section 12.3 of kernel_reference.md.
pub struct PrimaryEdgeField {
    pub field: Vec<Vec<f64>>,
    pub k: usize,
    pub n_edges: usize,
}

// ─── EdgeField ───────────────────────────────────────────────────────────────

/// Output of ABR kernel operators.
/// Section 12.4 of kernel_reference.md.
pub struct EdgeField {
    /// spatial[c][e] — component c, spatial edge e
    pub spatial: Vec<Vec<f64>>,
    /// comp[p][i] — component pair p, node i
    pub comp: Vec<Vec<f64>>,
    /// declared component relations
    pub comp_pairs: Vec<(usize, usize)>,
    pub k: usize,
}

// ─── PersistenceState ────────────────────────────────────────────────────────

/// Persistence state — the prior EdgeField required to evaluate persistence operators.
///
/// Can only be constructed from the kernel output of a completed prior declared
/// observation. Not from a model, parameter value, or static configuration.
///
/// `EdgeField::zero`, `PersistenceState::cold_start`, and `is_cold_start`
/// were removed at Kernel V8. There is no cold-start constructor.
/// Section 12.5 of kernel_reference.md.
pub struct PersistenceState {
    pub e_prior: EdgeField,
}

impl PersistenceState {
    /// Construct from the kernel output of a completed declared observation.
    /// `e_prior` must be the `EdgeField` returned by a prior call to
    /// `operator_e` or `operator_e_v5` over a declared observation.
    pub fn from_prior(e_prior: EdgeField) -> Self {
        PersistenceState { e_prior }
    }
}

// ─── PersistenceOutput ───────────────────────────────────────────────────────

/// Output of the persistence operator path A_p → B_p → R_p.
/// Section 12.6 of kernel_reference.md.
pub struct PersistenceOutput {
    pub a_persistence: Vec<Vec<f64>>,   // [c][e]
    pub b_persistence: Vec<Vec<f64>>,   // [c][e]
    pub r_persistence: Vec<Vec<f64>>,   // [c][e]
}

// ─── M-declaration enforcement ────────────────────────────────────────────────

/// Verify that ρ_base and χ₀ were declared by M.
///
/// The kernel holds no value for either and supplies no default.
/// This is not a missing implementation — it is the correct structure.
///
/// ρ_base (dimensionless ceiling) and χ₀ (reference scale for saturation)
/// are domain-specific. The complexity and characteristic scales of the
/// declared domain determine their applicable values. A hydrogen emission edge,
/// a geomagnetic current layer, and a neural coupling site each inhabit a
/// different relational scale and will have incommensurable values.
///
/// An application layer that assigns the same ρ_base and χ₀ across
/// different physical domains without independent M-declaration for each
/// is not applying the kernel correctly.
///
/// Section 11.3 of kernel_reference.md.
pub fn require_rho_declaration(rho_base: f64, chi_0: f64) {
    assert!(
        rho_base.is_finite(),
        "ρ_base must be declared by M as a finite value"
    );
    assert!(
        chi_0.is_finite() && chi_0 > 0.0,
        "χ₀ must be declared by M as a finite positive value in the dimension of χ"
    );
}

/// Verify that cc was declared by M for every declared component pair.
///
/// Cross-topology coupling coefficients (cc) are domain-specific for the
/// same reason ρ_base and χ₀ are: the coupling between two observable
/// families (e.g., spatial and angular momentum, electric and magnetic,
/// position and momentum) is determined by the relational structure of
/// the declared domain, not by any universal value. cc = 0.5 as a fixed
/// default was retired at Kernel V7.1 precisely because it imposed
/// cross-domain uniformity where none is warranted.
///
/// An empty cc with empty pairs is valid: it declares that no cross-topology
/// coupling is applicable in this domain at this declaration.
///
/// Section 11.3 of kernel_reference.md.
pub fn require_cc_declaration(cc: &[f64], pairs: &[(usize, usize)]) {
    assert_eq!(
        cc.len(), pairs.len(),
        "cc must be declared by M for every declared component pair"
    );
    assert!(
        cc.iter().all(|v| v.is_finite()),
        "cc values declared by M must be finite"
    );
}

// ─── ρ computation ────────────────────────────────────────────────────────────

/// Compute ρ for the primary kernel (Δ→Σ).
///
/// χ[i] = max |Δ(x)[c][e]| over all components c and edges e incident to i.
/// ρ[i] = ρ_base · χ[i] / (χ₀ + χ[i])
/// ρ[e] = ρ[source(e)]
///
/// Domain-specificity: χ[i] is calculable from declared observables alone.
/// ρ_base and χ₀ are not — they are domain-specific parameters that M must
/// supply. See `require_rho_declaration` for the structural reason.
///
/// OPEN: max-selection rule requires Origin declaration (section 11.2, 18).
///   This is a separate question from domain-specificity: even after M declares
///   ρ_base and χ₀ for this domain, the rule for combining χ over multiple
///   components and incident edges remains unconfirmed in the kernel reference.
/// OPEN: saturating form requires Origin declaration (section 11.2, 18).
///   The functional form ρ_base · χ/(χ₀+χ) is stated but its derivation is
///   not closed. A different form would still require domain-specific parameters.
pub fn compute_rho_primary(
    delta: &PrimaryEdgeField,
    rel: &DeclaredRelations,
    rho_base: f64,
    chi_0: f64,
) -> Vec<f64> {
    require_rho_declaration(rho_base, chi_0);
    let n_edges = rel.n_edges();

    let mut chi = vec![0.0_f64; rel.n_nodes];
    for e in 0..n_edges {
        let src = rel.src(e);
        let tgt = rel.tgt(e);
        for c in 0..delta.k {
            let v = delta.field[c][e].abs();
            if v > chi[src] { chi[src] = v; }
            if v > chi[tgt] { chi[tgt] = v; }
        }
    }

    let mut rho = vec![0.0_f64; n_edges];
    for e in 0..n_edges {
        let src = rel.src(e);
        rho[e] = rho_base * chi[src] / (chi_0 + chi[src]);
    }
    rho
}

/// Compute ρ for the ABR kernel (A→B→R).
///
/// χ[i] = max |A(x)[c][e]| over all components c and edges e incident to i.
/// ρ[i] = ρ_base · χ[i] / (χ₀ + χ[i])
/// ρ[e] = ρ[source(e)]
///
/// Domain-specificity: χ[i] is calculable from declared x alone.
/// ρ_base and χ₀ are domain-specific; see `require_rho_declaration`.
/// The same OPEN conditions as `compute_rho_primary` apply.
pub fn compute_rho(
    a_field: &EdgeField,
    rel: &DeclaredRelations,
    rho_base: f64,
    chi_0: f64,
) -> Vec<f64> {
    require_rho_declaration(rho_base, chi_0);
    let n_edges = rel.n_edges();

    let mut chi = vec![0.0_f64; rel.n_nodes];
    for e in 0..n_edges {
        let src = rel.src(e);
        let tgt = rel.tgt(e);
        for c in 0..a_field.k {
            let v = a_field.spatial[c][e].abs();
            if v > chi[src] { chi[src] = v; }
            if v > chi[tgt] { chi[tgt] = v; }
        }
    }

    let mut rho = vec![0.0_f64; n_edges];
    for e in 0..n_edges {
        let src = rel.src(e);
        rho[e] = rho_base * chi[src] / (chi_0 + chi[src]);
    }
    rho
}

/// Compute ρ for persistence operators.
/// Driven by A_persistence magnitudes.
///
/// Domain-specificity applies identically: ρ_base and χ₀ are domain-specific
/// regardless of whether the input field is a spatial A or a persistence A_p.
/// The same declared values from M apply across both kernel paths within a
/// single declared domain.
pub fn compute_rho_persistence(
    a_persistence: &[Vec<f64>],
    rel: &DeclaredRelations,
    rho_base: f64,
    chi_0: f64,
) -> Vec<f64> {
    require_rho_declaration(rho_base, chi_0);
    let n_edges = rel.n_edges();
    let k = a_persistence.len();

    let mut chi = vec![0.0_f64; rel.n_nodes];
    for e in 0..n_edges {
        let src = rel.src(e);
        let tgt = rel.tgt(e);
        for c in 0..k {
            let v = a_persistence[c][e].abs();
            if v > chi[src] { chi[src] = v; }
            if v > chi[tgt] { chi[tgt] = v; }
        }
    }

    let mut rho = vec![0.0_f64; n_edges];
    for e in 0..n_edges {
        let src = rel.src(e);
        rho[e] = rho_base * chi[src] / (chi_0 + chi[src]);
    }
    rho
}

// ─── Primary kernel: Δ → Σ ───────────────────────────────────────────────────

/// Δ operator.
///
/// Δ(x)[e] = x[s] − x[t], for each declared edge e = (s, t).
/// Section 11.1 of kernel_reference.md.
pub fn operator_delta(x: &NodeField, rel: &DeclaredRelations) -> PrimaryEdgeField {
    let n_edges = rel.n_edges();
    let mut field = vec![vec![0.0_f64; n_edges]; x.k];
    for e in 0..n_edges {
        let s = rel.src(e);
        let t = rel.tgt(e);
        for c in 0..x.k {
            field[c][e] = x.data[c][s] - x.data[c][t];
        }
    }
    PrimaryEdgeField { field, k: x.k, n_edges }
}

/// Σ operator.
///
/// Σ(g)[e] = g[e] + ρ[e] · (Σ_{adj⁺(e)} g − Σ_{adj⁻(e)} g)
/// g = Δ(x); immediate neighbours only.
/// Section 11.1 of kernel_reference.md.
pub fn operator_sigma(
    delta: &PrimaryEdgeField,
    rel: &DeclaredRelations,
    rho_base: f64,
    chi_0: f64,
) -> PrimaryEdgeField {
    let rho = compute_rho_primary(delta, rel, rho_base, chi_0);
    let n_edges = rel.n_edges();
    let mut field = vec![vec![0.0_f64; n_edges]; delta.k];
    for e in 0..n_edges {
        for c in 0..delta.k {
            let sum_plus:  f64 = rel.adj_plus[e].iter().map(|&f| delta.field[c][f]).sum();
            let sum_minus: f64 = rel.adj_minus[e].iter().map(|&f| delta.field[c][f]).sum();
            field[c][e] = delta.field[c][e] + rho[e] * (sum_plus - sum_minus);
        }
    }
    PrimaryEdgeField { field, k: delta.k, n_edges }
}

/// E_primary = Σ(Δ(x)).
/// Returns (Δ output, Σ output).
/// Section 11.1 of kernel_reference.md.
pub fn operator_e_primary(
    x: &NodeField,
    rel: &DeclaredRelations,
    rho_base: f64,
    chi_0: f64,
) -> (PrimaryEdgeField, PrimaryEdgeField) {
    let delta = operator_delta(x, rel);
    let sigma = operator_sigma(&delta, rel, rho_base, chi_0);
    (delta, sigma)
}

// ─── ABR kernel: A → B → R ───────────────────────────────────────────────────

/// A operator.
///
/// A(x)[e] = x[s] − x[t] (formula identical to Δ); spatial edges.
/// Component pairs (a,b): comp[p][i] = x[a][i] − x[b][i] at each node.
/// Section 11.1 of kernel_reference.md.
pub fn operator_a(
    f: &NodeField,
    rel: &DeclaredRelations,
    pairs: &[(usize, usize)],
) -> EdgeField {
    let n_edges = rel.n_edges();
    let k = f.k;

    let mut spatial = vec![vec![0.0_f64; n_edges]; k];
    for e in 0..n_edges {
        let s = rel.src(e);
        let t = rel.tgt(e);
        for c in 0..k {
            spatial[c][e] = f.data[c][s] - f.data[c][t];
        }
    }

    let mut comp = vec![vec![0.0_f64; f.n]; pairs.len()];
    for (p, &(a, b)) in pairs.iter().enumerate() {
        assert!(a < k && b < k,
            "component pair ({}, {}) out of range for NodeField with {} components", a, b, k);
        for i in 0..f.n {
            comp[p][i] = f.data[a][i] - f.data[b][i];
        }
    }

    EdgeField { spatial, comp, comp_pairs: pairs.to_vec(), k }
}

/// B operator.
///
/// B(g)[e] = g[e] + Σ_{f ∈ succ(e)} g[f]; immediate successors only.
/// Terminal edges accumulate nothing (empty succ → no contribution).
/// Section 11.1 of kernel_reference.md.
pub fn operator_b(g: &EdgeField, rel: &DeclaredRelations) -> EdgeField {
    let n_edges = rel.n_edges();
    let mut spatial = vec![vec![0.0_f64; n_edges]; g.k];
    for e in 0..n_edges {
        for c in 0..g.k {
            let sum_succ: f64 = rel.adj_plus[e].iter().map(|&f| g.spatial[c][f]).sum();
            spatial[c][e] = g.spatial[c][e] + sum_succ;
        }
    }
    EdgeField {
        spatial,
        comp: g.comp.clone(),
        comp_pairs: g.comp_pairs.clone(),
        k: g.k,
    }
}

/// R operator.
///
/// Spatial term:
///   R(g)[c][e] = g[c][e] + ρ[src(e)] · (Σ_{succ(e)} g[c] − Σ_{pred(e)} g[c])
///
/// Cross-topology term: for each declared component pair p = (a, b),
///   the component difference at src(e) is added to spatial channels a and b,
///   scaled by cc[p]. Direction preserved from the declared pair ordering.
///
/// Section 11.1 of kernel_reference.md.
pub fn operator_r(
    bg: &EdgeField,
    rel: &DeclaredRelations,
    rho: &[f64],
    cc: &[f64],
) -> EdgeField {
    require_cc_declaration(cc, &bg.comp_pairs);
    let n_edges = rel.n_edges();
    let mut spatial = vec![vec![0.0_f64; n_edges]; bg.k];

    for e in 0..n_edges {
        let src = rel.src(e);

        // Spatial antisymmetric term
        for c in 0..bg.k {
            let sum_succ: f64 = rel.adj_plus[e].iter().map(|&f| bg.spatial[c][f]).sum();
            let sum_pred: f64 = rel.adj_minus[e].iter().map(|&f| bg.spatial[c][f]).sum();
            spatial[c][e] = bg.spatial[c][e] + rho[e] * (sum_succ - sum_pred);
        }

        // Cross-topology coupling for each declared component pair
        for (p, &(a, b)) in bg.comp_pairs.iter().enumerate() {
            let cross = bg.comp[p][src] * cc[p];
            spatial[a][e] += cross;
            spatial[b][e] -= cross;
        }
    }

    EdgeField {
        spatial,
        comp: bg.comp.clone(),
        comp_pairs: bg.comp_pairs.clone(),
        k: bg.k,
    }
}

/// E (Phase 1): R(B(A(x)), ρ(A(x)))
///
/// Full ABR path. Requires at least one interior locus (full-operator
/// admissibility condition, section 10 of kernel_reference.md).
/// Section 11.1 of kernel_reference.md.
pub fn operator_e(
    f: &NodeField,
    rel: &DeclaredRelations,
    pairs: &[(usize, usize)],
    cc: &[f64],
    rho_base: f64,
    chi_0: f64,
) -> EdgeField {
    let a = operator_a(f, rel, pairs);
    let rho = compute_rho(&a, rel, rho_base, chi_0);
    let b = operator_b(&a, rel);
    operator_r(&b, rel, &rho, cc)
}

// ─── Persistence operators ────────────────────────────────────────────────────

/// A_persistence operator.
///
/// A_persistence[e] = E_current[e] − E_prior[e]; direction fixed.
/// Section 11.1 of kernel_reference.md.
pub fn operator_a_persistence(
    e_current: &EdgeField,
    e_prior: &EdgeField,
) -> Vec<Vec<f64>> {
    assert_eq!(e_current.k, e_prior.k, "A_persistence: component count mismatch");
    let n_edges = e_current.spatial[0].len();
    assert_eq!(e_prior.spatial[0].len(), n_edges, "A_persistence: edge count mismatch");
    let mut out = vec![vec![0.0_f64; n_edges]; e_current.k];
    for c in 0..e_current.k {
        for e in 0..n_edges {
            out[c][e] = e_current.spatial[c][e] - e_prior.spatial[c][e];
        }
    }
    out
}

/// B_persistence operator.
///
/// B form over A_persistence: immediate successor accumulation over relational steps.
/// Section 11.1 of kernel_reference.md.
pub fn operator_b_persistence(
    a_persistence: &[Vec<f64>],
    rel: &DeclaredRelations,
) -> Vec<Vec<f64>> {
    let n_edges = rel.n_edges();
    let k = a_persistence.len();
    let mut out = vec![vec![0.0_f64; n_edges]; k];
    for e in 0..n_edges {
        for c in 0..k {
            let sum_succ: f64 = rel.adj_plus[e].iter().map(|&f| a_persistence[c][f]).sum();
            out[c][e] = a_persistence[c][e] + sum_succ;
        }
    }
    out
}

/// R_persistence operator.
///
/// R form over B_persistence; spatial component only.
/// Section 11.1 of kernel_reference.md.
pub fn operator_r_persistence(
    b_persistence: &[Vec<f64>],
    rel: &DeclaredRelations,
    rho_persistence: &[f64],
) -> Vec<Vec<f64>> {
    let n_edges = rel.n_edges();
    let k = b_persistence.len();
    let mut out = vec![vec![0.0_f64; n_edges]; k];
    for e in 0..n_edges {
        for c in 0..k {
            let sum_succ: f64 = rel.adj_plus[e].iter().map(|&f| b_persistence[c][f]).sum();
            let sum_pred: f64 = rel.adj_minus[e].iter().map(|&f| b_persistence[c][f]).sum();
            out[c][e] = b_persistence[c][e] + rho_persistence[e] * (sum_succ - sum_pred);
        }
    }
    out
}

/// E (Phases 1+2): Phase 1 (A→B→R), then A_p → B_p → R_p.
///
/// Usage pattern:
///   At the first declared observation, call `operator_e` (Phase 1 only).
///   At the second and subsequent observations, call this function.
///   `persistence_state` must be constructed from `PersistenceState::from_prior(e1)`.
///
/// Returns (Phase-1 EdgeField, PersistenceOutput).
/// Section 11.6 of kernel_reference.md.
pub fn operator_e_v5(
    f: &NodeField,
    rel: &DeclaredRelations,
    pairs: &[(usize, usize)],
    cc: &[f64],
    persistence_state: &PersistenceState,
    rho_base: f64,
    chi_0: f64,
) -> (EdgeField, PersistenceOutput) {
    // Phase 1: A→B→R
    let e_current = operator_e(f, rel, pairs, cc, rho_base, chi_0);

    // Phase 2: A_p → B_p → R_p
    let a_p = operator_a_persistence(&e_current, &persistence_state.e_prior);
    let b_p = operator_b_persistence(&a_p, rel);
    let rho_p = compute_rho_persistence(&a_p, rel, rho_base, chi_0);
    let r_p = operator_r_persistence(&b_p, rel, &rho_p);

    let persistence = PersistenceOutput {
        a_persistence: a_p,
        b_persistence: b_p,
        r_persistence: r_p,
    };
    (e_current, persistence)
}

// ─── Structural checks ────────────────────────────────────────────────────────

/// Relational isolation check.
///
/// Returns true when every edge has empty adj⁺ and adj⁻ (no successors
/// or predecessors). In this case Σ's and R's antisymmetric terms are
/// structurally zero.
/// Section 11.5 of kernel_reference.md.
pub fn relational_isolation(rel: &DeclaredRelations) -> bool {
    let n_edges = rel.n_edges();
    (0..n_edges).all(|e| rel.adj_plus[e].is_empty() && rel.adj_minus[e].is_empty())
}

/// Declared edge-image admissibility check.
///
/// Returns true when no edge vector is the negation of another declared edge vector.
/// `tol` is an IMPLEMENTATION-ONLY NUMERICAL TOLERANCE guarding finite-precision
/// arithmetic. It is not a property of the observed system.
/// Section 11.5 of kernel_reference.md.
pub fn declared_edge_image_admissibility_check(delta: &PrimaryEdgeField, tol: f64) -> bool {
    let n_edges = delta.n_edges;
    for e in 0..n_edges {
        for f in (e + 1)..n_edges {
            // Check if delta[·][e] ≈ -delta[·][f] for all components
            let negation = (0..delta.k).all(|c| {
                (delta.field[c][e] + delta.field[c][f]).abs() <= tol
            });
            if negation {
                return false;
            }
        }
    }
    true
}

/// Extract the antisymmetric term of Σ separately.
///
/// antisymmetric_term[c][e] = ρ[e] · (Σ_{adj⁺(e)} Δ[c] − Σ_{adj⁻(e)} Δ[c])
///
/// `tol` is an IMPLEMENTATION-ONLY NUMERICAL TOLERANCE. Not a system property.
/// Section 11.5 of kernel_reference.md.
pub fn antisymmetric_term(
    delta: &PrimaryEdgeField,
    rel: &DeclaredRelations,
    rho_base: f64,
    chi_0: f64,
) -> PrimaryEdgeField {
    let rho = compute_rho_primary(delta, rel, rho_base, chi_0);
    let n_edges = rel.n_edges();
    let mut field = vec![vec![0.0_f64; n_edges]; delta.k];
    for e in 0..n_edges {
        for c in 0..delta.k {
            let sum_plus:  f64 = rel.adj_plus[e].iter().map(|&f| delta.field[c][f]).sum();
            let sum_minus: f64 = rel.adj_minus[e].iter().map(|&f| delta.field[c][f]).sum();
            field[c][e] = rho[e] * (sum_plus - sum_minus);
        }
    }
    PrimaryEdgeField { field, k: delta.k, n_edges }
}

/// IRRS Session — Interactive D/M-Driven Relational Computation
///
/// Provides the minimal interactive session layer over Kernel V8:
///
///   1. Accept a bounded D and M (declare_topology, declare_field,
///      declare_rho, declare_cc).
///   2. Check admission prerequisites (admit).
///   3. Execute the applicable frozen Kernel V8 operators (execute).
///   4. Expose the mathematical trace and parameter provenance (trace_report).
///
/// This crate does not modify the kernel. All operator mathematics are
/// executed by `irrs-kernel` unchanged.
///
/// Domain-specificity: ρ_base, χ₀, and cc are domain-specific by reason
/// of complexity. See `irrs-kernel` documentation for the structural
/// explanation. This session layer enforces the distinction between
/// illustrative and observationally established parameters.

pub mod admission;
pub mod session;

/// IRRS Session — D/M Declaration and Kernel Execution
///
/// Accepts a bounded D and M, validates declarations, checks admission,
/// executes Kernel V8 operators, and reports the mathematical trace with
/// parameter provenance.
///
/// Session is stateful: declarations accumulate until execute() is called.
/// No operator is applied before prerequisites are satisfied.
///
/// Execution order:
///   1. Pre-execution validation (dimensions, parameter admissibility)
///   2. Topology + interior locus check → Blocked if insufficient
///   3. A and B computed (topology + field sufficient)
///   4. R prerequisites check → Partial if ρ unmet, Complete otherwise
///
/// Continuous Relational Process Rule: every evaluation enters an already-
/// existing process. This session layer does not construct synthetic cold
/// starts. PersistenceState is not available here; the session executes the
/// spatial A→B→R path only.

use irrs_kernel::operators::{
    DeclaredRelations, NodeField,
    operator_a, operator_b, operator_r,
    compute_rho,
    require_rho_declaration, require_cc_declaration,
};

use crate::admission::{
    AdmissionResult, EvaluatedComparison, ExecutionResult, KernelOpenCondition,
    OpenCondition, ParameterProvenance, SessionOutput,
    DETECTION_TOLERANCE,
};

// ─── Session ─────────────────────────────────────────────────────────────────

/// Interactive session for D/M-driven relational computation.
///
/// Workflow:
///   1. `declare_topology` — supply DeclaredRelations
///   2. `declare_field`    — supply NodeField
///   3. `declare_rho`      — supply ρ_base, χ₀, and ParameterProvenance
///                           (ObservationallyEstablished requires EvidenceRecord)
///   4. `declare_cc`       — supply cross-topology coupling (may be empty)
///   5. `admit`            — check prerequisites; inspect OpenConditions if any
///   6. `execute`          — run frozen Kernel V8 operators; get SessionOutput
///   7. `trace_report`     — print mathematical trace and provenance
pub struct Session {
    rel:   Option<DeclaredRelations>,
    field: Option<NodeField>,
    /// (ρ_base, χ₀, provenance)
    rho:   Option<(f64, f64, ParameterProvenance)>,
    cc:    Vec<f64>,
    pairs: Vec<(usize, usize)>,
}

impl Session {
    /// Create an empty session. No declarations are present.
    pub fn new() -> Self {
        Session {
            rel:   None,
            field: None,
            rho:   None,
            cc:    vec![],
            pairs: vec![],
        }
    }

    /// Declare the relational topology (D).
    ///
    /// Every edge must carry an explicit provenance. Persistence edges are not
    /// declared here; they belong to PersistenceState in a separate evaluation.
    pub fn declare_topology(&mut self, rel: DeclaredRelations) {
        self.rel = Some(rel);
    }

    /// Declare the node field (M: O → D).
    ///
    /// data[c][i] is the numerical projection through M at component c, node i.
    /// All values must be finite (∈ D). field.n must equal the number of nodes
    /// in the declared topology; mismatches are caught at execute() time.
    pub fn declare_field(&mut self, field: NodeField) {
        self.field = Some(field);
    }

    /// Declare domain-specific parameters ρ_base and χ₀ with their provenance.
    ///
    /// These are not defaults, universal constants, or placeholders.
    /// Complexity of the declared domain determines the applicable values.
    ///
    /// `provenance` must honestly describe how the values were established:
    ///   - `Illustrative` — chosen to demonstrate operator mechanics
    ///   - `ObservationallyEstablished(evidence)` — calibrated against
    ///     independently observable R output; an `EvidenceRecord` is required
    ///
    /// Parameter admissibility (χ₀ > 0, ρ_base ≥ 0) is checked at execute().
    pub fn declare_rho(
        &mut self,
        rho_base:   f64,
        chi_0:      f64,
        provenance: ParameterProvenance,
    ) {
        self.rho = Some((rho_base, chi_0, provenance));
    }

    /// Declare cross-topology coupling values cc with corresponding component pairs.
    ///
    /// The fixed cc = 0.5 default was retired at Kernel V7.1. Coupling
    /// between families must be M-declared per domain. If the declared
    /// topology has no cross-family edges, pass empty vecs (the default).
    pub fn declare_cc(&mut self, cc: Vec<f64>, pairs: Vec<(usize, usize)>) {
        self.cc    = cc;
        self.pairs = pairs;
    }

    // ─── Kernel OPEN conditions ───────────────────────────────────────────────

    /// Return the Kernel V8 mathematical conditions that remain unresolved
    /// regardless of session declarations. These are always present when R
    /// is evaluated; they do not block execution but must be surfaced.
    pub fn kernel_open_conditions() -> Vec<KernelOpenCondition> {
        vec![
            KernelOpenCondition::RhoMaxSelectionRule,
            KernelOpenCondition::RhoSaturatingForm,
        ]
    }

    // ─── Pre-execution validation ─────────────────────────────────────────────

    /// Validate declared values before any operator is called.
    ///
    /// Checks:
    ///   - field.n == topology.n_nodes (dimension compatibility)
    ///   - χ₀ > 0 (strictly positive; appears as denominator in ρ formula)
    ///   - ρ_base ≥ 0 (dimensionless ceiling; must be non-negative)
    ///
    /// Returns a list of `OpenCondition::DimensionMismatch` or
    /// `OpenCondition::InvalidRhoParameter` items. Empty means valid.
    fn validate(&self) -> Vec<OpenCondition> {
        let mut errors: Vec<OpenCondition> = vec![];

        // Dimension check: field nodes must equal topology nodes.
        if let (Some(rel), Some(field)) = (&self.rel, &self.field) {
            if field.n != rel.n_nodes {
                errors.push(OpenCondition::DimensionMismatch {
                    field_nodes:    field.n,
                    topology_nodes: rel.n_nodes,
                });
            }
        }

        // ρ parameter admissibility.
        if let Some((rho_base, chi_0, _)) = &self.rho {
            if *chi_0 <= 0.0 {
                errors.push(OpenCondition::InvalidRhoParameter(format!(
                    "χ₀ must be strictly positive (got {}); it appears as a denominator \
                     in ρ[e] = ρ_base·χ[src(e)] / (χ₀ + χ[src(e)])",
                    chi_0
                )));
            }
            if *rho_base < 0.0 {
                errors.push(OpenCondition::InvalidRhoParameter(format!(
                    "ρ_base must be non-negative (got {}); it is a dimensionless ceiling",
                    rho_base
                )));
            }
        }

        errors
    }

    // ─── Interior locus check ─────────────────────────────────────────────────

    fn has_interior_locus(rel: &DeclaredRelations) -> bool {
        (0..rel.n_nodes).any(|t| {
            let has_incoming = (0..rel.n_edges()).any(|e| rel.tgt(e) == t);
            let has_outgoing = (0..rel.n_edges()).any(|f| rel.src(f) == t);
            has_incoming && has_outgoing
        })
    }

    // ─── Admission check ─────────────────────────────────────────────────────

    /// Check whether A→B→R is admissible given current declarations.
    ///
    /// Returns `Admitted` if all prerequisites are met (including dimension
    /// validation and ρ parameter admissibility).
    /// Returns `Open(conditions)` listing every unmet prerequisite.
    ///
    /// `Admitted` also carries `kernel_open` — the Kernel V8 mathematical
    /// questions that remain unresolved regardless of session declarations.
    ///
    /// Does not execute any operator. Does not fabricate values.
    pub fn admit(&self) -> AdmissionResult {
        // Validation errors block admission.
        let validation_errors = self.validate();
        if !validation_errors.is_empty() {
            return AdmissionResult::Open(validation_errors);
        }

        let mut open: Vec<OpenCondition> = vec![];

        // Prerequisite 1: topology declared.
        let rel = match &self.rel {
            Some(r) => r,
            None => {
                open.push(OpenCondition::TopologyNotDeclared);
                if self.field.is_none() { open.push(OpenCondition::NodeFieldNotDeclared); }
                if self.rho.is_none()   { open.push(OpenCondition::RhoNotDeclared); }
                return AdmissionResult::Open(open);
            }
        };

        // Prerequisite 2: interior locus.
        if !Self::has_interior_locus(rel) {
            open.push(OpenCondition::NoInteriorLocus);
        }

        // Prerequisite 3: node field.
        if self.field.is_none() {
            open.push(OpenCondition::NodeFieldNotDeclared);
        }

        // Prerequisite 4: ρ_base and χ₀.
        if self.rho.is_none() {
            open.push(OpenCondition::RhoNotDeclared);
        }

        if open.is_empty() {
            AdmissionResult::Admitted {
                parameter_provenance: self.rho.as_ref().unwrap().2.clone(),
                kernel_open:          Self::kernel_open_conditions(),
            }
        } else {
            AdmissionResult::Open(open)
        }
    }

    // ─── Execution ───────────────────────────────────────────────────────────

    /// Execute frozen Kernel V8 operators A→B→R.
    ///
    /// Returns `SessionOutput`:
    ///   `Complete`  — all prerequisites met; full A→B→R executed
    ///   `Partial`   — topology and field declared, ρ unmet; A and B computed
    ///   `Blocked`   — missing declarations or validation failure; nothing computed
    ///
    /// When ρ is not declared but topology and field are present, A and B are
    /// computed and returned in `Partial`. R is not fabricated.
    ///
    /// Detection indicators 𝟙[e] are evaluated across ALL declared components
    /// and ALL edges. DETECTION_TOLERANCE is explicit; see its documentation
    /// for the distinction between numerical zero and physical detection.
    ///
    /// The kernel operators are called unchanged. No operator mathematics
    /// are implemented in this crate.
    pub fn execute(&self) -> SessionOutput {
        // Step 1: pre-execution validation (dimensions, ρ admissibility).
        let validation_errors = self.validate();
        if !validation_errors.is_empty() {
            return SessionOutput::Blocked(validation_errors);
        }

        // Step 2: require topology and field to compute A and B.
        let (rel, field) = match (&self.rel, &self.field) {
            (Some(r), Some(f)) => (r, f),
            _ => {
                let mut conditions = vec![];
                if self.rel.is_none()   { conditions.push(OpenCondition::TopologyNotDeclared); }
                if self.field.is_none() { conditions.push(OpenCondition::NodeFieldNotDeclared); }
                if self.rho.is_none()   { conditions.push(OpenCondition::RhoNotDeclared); }
                return SessionOutput::Blocked(conditions);
            }
        };

        // Step 3: interior locus required before any operator acts.
        if !Self::has_interior_locus(rel) {
            return SessionOutput::Blocked(vec![OpenCondition::NoInteriorLocus]);
        }

        // A and B are computable. Compute them using frozen kernel operators.
        // A: edge differences — x[src(e)] − x[tgt(e)] for each edge e.
        let a = operator_a(field, rel, &self.pairs);
        // B: accumulates immediate successor A values — B[e] = A[e] + Σ_{succ(e)} A.
        let b = operator_b(&a, rel);

        // Step 4: require ρ to compute R.
        let (rho_base, chi_0, provenance) = match &self.rho {
            Some(triple) => (&triple.0, &triple.1, &triple.2),
            None => {
                return SessionOutput::Partial {
                    a_field:           a,
                    b_field:           b,
                    open_r_conditions: vec![OpenCondition::RhoNotDeclared],
                    kernel_open:       Self::kernel_open_conditions(),
                };
            }
        };

        // Validate M-declared parameters through kernel enforcement functions.
        // (These assert on violation; validation above ensures we reach here safely.)
        require_rho_declaration(*rho_base, *chi_0);
        require_cc_declaration(&self.cc, &self.pairs);

        // ρ[e] per edge — computed from A magnitudes and M-declared ρ_base, χ₀.
        let rho = compute_rho(&a, rel, *rho_base, *chi_0);

        // R: adds antisymmetric circulation term — R[c][e] = B[c][e] + ρ[e]·(Σ_succ B − Σ_pred B).
        let r = operator_r(&b, rel, &rho, &self.cc);

        // Detection indicators: 𝟙[e] = 1 iff antisymmetric term is numerically
        // nonzero for ANY declared component c at edge e.
        // Checked across ALL components, not only c=0.
        let detection_indicators: Vec<f64> = (0..rel.n_edges())
            .map(|e| {
                let any_nonzero = (0..r.k).any(|c| {
                    (r.spatial[c][e] - b.spatial[c][e]).abs() > DETECTION_TOLERANCE
                });
                if any_nonzero { 1.0 } else { 0.0 }
            })
            .collect();

        let all_zero = detection_indicators.iter().all(|&v| v == 0.0);
        let prov        = provenance.clone();
        let kernel_open = Self::kernel_open_conditions();

        // Evaluate declared comparisons against actual kernel output.
        // Only populated when provenance is ObservationallyVerified.
        // `calculated` comes from the kernel result, never from the caller.
        let evaluated_comparisons: Vec<EvaluatedComparison> = match provenance {
            ParameterProvenance::ObservationallyVerified(rec) => {
                rec.comparisons.iter().map(|c| {
                    let calculated =
                        if c.component < r.k && c.edge_index < r.spatial[c.component].len() {
                            r.spatial[c.component][c.edge_index]
                        } else {
                            f64::NAN  // out-of-bounds declaration → fails comparison
                        };
                    EvaluatedComparison {
                        label:      c.label.clone(),
                        observed:   c.observed,
                        calculated,
                        tolerance:  c.tolerance,
                    }
                }).collect()
            }
            _ => vec![],
        };

        if all_zero {
            SessionOutput::Complete(ExecutionResult::CalculatedZero {
                edge_field:            r,
                parameter_provenance:  prov,
                kernel_open,
                evaluated_comparisons,
            })
        } else {
            SessionOutput::Complete(ExecutionResult::RelationalOutput {
                edge_field:            r,
                parameter_provenance:  prov,
                detection_indicators,
                kernel_open,
                evaluated_comparisons,
            })
        }
    }

    // ─── Trace report ────────────────────────────────────────────────────────

    /// Print the mathematical trace and provenance for any SessionOutput.
    ///
    /// This report distinguishes:
    ///   CALCULATED  — quantities from declared topology and node field alone
    ///   M-SUPPLIED  — ρ_base, χ₀ with their provenance label
    ///   KERNEL OPEN — unresolved Kernel V8 mathematical conditions
    ///   RESULT      — Complete (RelationalOutput / CalculatedZero) or Partial
    pub fn trace_report(&self, output: &SessionOutput) {
        // Extract session-evaluated comparisons (actual kernel output vs declared).
        // These are used both in the M-SUPPLIED PARAMETERS section (for the
        // comparison table) and for the result label.
        let evaluated: &[EvaluatedComparison] = match output {
            SessionOutput::Complete(ExecutionResult::RelationalOutput {
                evaluated_comparisons, ..
            })
            | SessionOutput::Complete(ExecutionResult::CalculatedZero {
                evaluated_comparisons, ..
            }) => evaluated_comparisons.as_slice(),
            _ => &[],
        };

        println!();
        println!("═══════════════════════════════════════════════════════");
        println!("  IRRS SESSION — EXECUTION TRACE");
        println!("═══════════════════════════════════════════════════════");

        // Topology
        if let Some(rel) = &self.rel {
            println!();
            println!("  DECLARED TOPOLOGY  ({} nodes, {} edges)",
                rel.n_nodes, rel.n_edges());
            for e in 0..rel.n_edges() {
                println!("    e{}: node {} → node {}  [{:?}]",
                    e, rel.src(e), rel.tgt(e), rel.provenance(e));
            }
        } else {
            println!();
            println!("  DECLARED TOPOLOGY  [not declared]");
        }

        // Node field
        if let Some(field) = &self.field {
            println!();
            let comp_label = if field.k == 1 { "1 component".to_string() }
                             else { format!("{} components", field.k) };
            println!("  DECLARED NODE FIELD  ({})", comp_label);
            for c in 0..field.k {
                for i in 0..field.n {
                    println!("    x[c={},i={}] = {}", c, i, field.data[c][i]);
                }
            }
        } else {
            println!();
            println!("  DECLARED NODE FIELD  [not declared]");
        }

        // M-supplied parameters
        println!();
        if let Some((rho_base, chi_0, provenance)) = &self.rho {
            println!("  M-SUPPLIED PARAMETERS  [{}]", provenance.label());
            println!("    ρ_base = {}   (domain-specific ceiling; complexity-determined)", rho_base);
            println!("    χ₀     = {}   (domain-specific saturation scale; complexity-determined)", chi_0);
            match provenance {
                ParameterProvenance::Illustrative => {
                    println!();
                    println!("  NOTE: Illustrative parameters enable operator demonstration.");
                    println!("  No observational correspondence is claimed.");
                    println!("  To reach EVIDENCE DECLARED status, supply an EvidenceRecord.");
                    println!("  To reach OBSERVATIONALLY VERIFIED status, supply a VerificationRecord");
                    println!("  with declared observables, parameter derivation, comparison results,");
                    println!("  and verification source.");
                }
                ParameterProvenance::EvidenceDeclared(ev) => {
                    println!();
                    println!("  EVIDENCE RECORD:");
                    println!("    {}", ev.description);
                    if let Some(r) = &ev.reference {
                        println!("    Reference: {}", r);
                    }
                    println!();
                    println!("  VERIFICATION STATUS: OPEN");
                    println!("  The evidence record declares the basis for these parameters.");
                    println!("  It has not been independently evaluated. To reach OBSERVATIONALLY");
                    println!("  VERIFIED, supply a VerificationRecord with declared observables,");
                    println!("  parameter derivation, comparison results, and verification source.");
                }
                ParameterProvenance::ObservationallyVerified(rec) => {
                    println!();
                    println!("  EVIDENCE RECORD:");
                    println!("    {}", rec.evidence.description);
                    if let Some(r) = &rec.evidence.reference {
                        println!("    Reference: {}", r);
                    }
                    println!();
                    println!("  PARAMETER DERIVATION:");
                    println!("    {}", rec.parameter_derivation);
                    println!();
                    println!("  VERIFICATION SOURCE: {}", rec.verification_source);
                    if !rec.declared_observables.is_empty() {
                        println!();
                        println!("  DECLARED OBSERVABLES:");
                        for obs in &rec.declared_observables {
                            let unit = obs.unit.as_deref().unwrap_or("dimensionless");
                            println!("    {} = {}  [{}]  ({})",
                                obs.label, obs.value, unit, obs.measurement_provenance);
                        }
                    }
                    // Show session-evaluated comparisons (actual kernel output).
                    if !evaluated.is_empty() {
                        println!();
                        println!("  OBSERVATIONAL COMPARISONS (kernel output vs declared):");
                        let mut n_failed = 0usize;
                        for cmp in evaluated {
                            let status = if cmp.passes() { "PASS" } else { n_failed += 1; "FAIL" };
                            println!("    {}  observed={:.6}  calculated={:.6}  \
                                     residual={:+.6}  tol={:.2e}  [{}]",
                                cmp.label, cmp.observed, cmp.calculated,
                                cmp.residual(), cmp.tolerance, status);
                        }
                        if n_failed > 0 {
                            println!();
                            println!("  ⚠ FAILED COMPARISONS: {}", n_failed);
                            println!("  The kernel-calculated result stands as computed.");
                            println!("  Declared observables and actual kernel output disagree");
                            println!("  beyond declared tolerance. The mathematical result has");
                            println!("  not been rewritten to match the declared observable.");
                        }
                    } else if rec.comparisons.is_empty() {
                        println!();
                        println!("  COMPARISONS: none declared — correspondence OPEN");
                    }
                    if !rec.open_items.is_empty() {
                        println!();
                        println!("  OPEN VERIFICATION ITEMS:");
                        for item in &rec.open_items {
                            println!("    ✗ {}", item);
                        }
                    }
                }
            }
        } else {
            println!("  M-SUPPLIED PARAMETERS  [not declared]");
            println!("    ρ_base and χ₀ are domain-specific and must be declared.");
        }

        // Kernel OPEN conditions — always surfaced
        println!();
        println!("  KERNEL V8 OPEN CONDITIONS (unresolved mathematical questions):");
        println!("    ① RhoMaxSelectionRule  — χ magnitude selection across components");
        println!("      and incident edges unconfirmed (§11.2, §18).");
        println!("    ② RhoSaturatingForm    — saturating form ρ=ρ_base·χ/(χ₀+χ) not");
        println!("      derived from relational first principles (§11.2, §18).");

        // Execution result
        println!();
        match output {
            SessionOutput::Blocked(conditions) => {
                println!("  RESULT: BLOCKED");
                for c in conditions {
                    println!("    ✗ {:?}", c);
                }
            }

            SessionOutput::Partial { a_field, b_field, open_r_conditions, .. } => {
                let rel = self.rel.as_ref().unwrap();
                println!("  RESULT: PARTIAL EXECUTION — A and B computed; R blocked");
                println!();
                println!("  A[e] (edge differences, all components):");
                for c in 0..a_field.k {
                    for e in 0..rel.n_edges() {
                        println!("    A[c={},e{}] = {:.6}", c, e, a_field.spatial[c][e]);
                    }
                }
                println!();
                println!("  B[e] (successor accumulation, all components):");
                for c in 0..b_field.k {
                    for e in 0..rel.n_edges() {
                        println!("    B[c={},e{}] = {:.6}", c, e, b_field.spatial[c][e]);
